            1 => (Count: 349267, IndexCount: 688548, Weights: Weights1, Edges: Edges1, Interior: Interior1, ExtraWeights: ExtraWeights1, Fragments: Fragments1),
            _ => throw new ArgumentOutOfRangeException(nameof(lod))
        };
        if (source.Length != data.Count || positions.Length != data.Count || indices.Length != data.IndexCount || !float.IsFinite(delta))
            throw new InvalidOperationException("Lift03 joined shells require their recorded native layout.");
        foreach (var item in data.Weights)
            positions[item.Index].x = source[item.Index].x + item.Weight * delta;
        var x = new float[data.ExtraWeights.Length];
        for (var i = 0; i < data.Edges.Length; i++)
        {
            var edge = data.Edges[i];
            x[i] = source[edge.A].x + (source[edge.B].x - source[edge.A].x) * edge.Fraction + data.ExtraWeights[i] * delta;
        }
        for (var i = 0; i < data.Interior.Length; i++)
        {
            var a = data.Interior[i];
            var index = data.Edges.Length + i;
            x[index] = source[a.A].x + (source[a.B].x - source[a.A].x) * a.WeightB + (source[a.C].x - source[a.A].x) * a.WeightC + data.ExtraWeights[index] * delta;
        }
        return new MovableStructureModel.Plan(source, positions, new[] { indices }, new[] { new bool[indices.Length / 3] },
            addedVertices: data.Edges, fragments: data.Fragments, interiorVertices: data.Interior, constructedX: x);
    }
